customCSS:
.t, .history { color: #737994; }
.join { color: #a6d189; }
.part, .quit { color: #737994; }
.kick, .error { color: #e78284; }
.notice { color: #e5c890; }
.action { color: #ca9ee6; }
.mode, .nick, .topic, .server { color: #81c8be; }
.highlight { color: #c6d0f5; background-color: #51576d; border-left: 3px solid #ca9ee6; padding-left: 8px; }
.reply { color: #737994; border-left: 2px solid #8caaee; padding-left: 6px; }
.oper { color: #303446; background-color: #e5c890; }
.reactions { color: #8caaee; background-color: #414559; }
.card { background-color: #414559; border-color: #737994; }
.card-title { color: #8caaee; }
.card-desc { color: #737994; }
.daychange { color: #737994; border-color: #414559; }
